#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a s/N gate; returns success on sim or yes.
confirm() {
  local reply=""
  printf '  %s? %s [s/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[SsYy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Primeira subida do Decupa com o perfil Tailscale (docs/implantacao-docker.md,
# "Acesso pela rede Tailscale"). Rode no host, de qualquer pasta:
#   bash scripts/tailscale-primeira-subida.sh

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
DOCKER=(docker)
PASSED=()
FAILED=()
HOST_IN_TAILNET=0

compose() { "${DOCKER[@]}" compose "$@"; }

# remove_env KEY tira a linha KEY= do ENV_FILE, mantendo modo e dono do arquivo.
remove_env() {
  local key="$1" tmp kept=()
  [[ -f "$ENV_FILE" ]] || return 0
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  for k in "${WRITTEN_ENV[@]}"; do [[ "$k" == "$key" ]] || kept+=("$k"); done
  WRITTEN_ENV=("${kept[@]}")
  printf '  %s✓ removi%s %s de %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# check "Pergunta" "nome" registra o resultado de uma conferência humana.
check() {
  if confirm "$1"; then
    PASSED+=("$2")
    printf '  %s✓ %s%s\n' "$GREEN" "$2" "$RESET"
  else
    FAILED+=("$2")
    SKIPPED+=("conferência que não passou: $2")
    warn "$2 não passou. Siga em frente para ver o resto ou pare com Ctrl-C para corrigir."
  fi
  pause
}

# Nome que o serve publicou, sem esquema, porta ou barra: decupa.tail1234.ts.net
serve_domain() {
  local out url
  out=$(compose exec -T tailscale tailscale serve status 2>&1 || true)
  url=$(grep -o 'https://[^ ]*' <<<"$out" | head -n1 || true)
  url="${url#https://}"; url="${url%%/*}"; url="${url%:443}"
  printf '%s' "${url,,}"
}

run_wizard() {

TOTAL_STAGES=12
cd "$ROOT"

banner "Decupa: primeira subida com Tailscale"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Conferir o host"
if [[ ! -f docker-compose.tailscale.yml || ! -f docker/tailscale/serve.json ]]; then
  warn "Este checkout não tem docker-compose.tailscale.yml e docker/tailscale/serve.json."
  say "Atualize o repositório no host para a versão com o perfil Tailscale e rode de novo."
  exit 1
fi
command -v docker >/dev/null 2>&1 || { warn "Docker não encontrado neste host."; exit 1; }
if docker info >/dev/null 2>&1; then
  DOCKER=(docker)
elif command -v sudo >/dev/null 2>&1 && confirm "Seu usuário não acessa o Docker. Usar sudo docker nesta execução?"; then
  DOCKER=(sudo docker)
  "${DOCKER[@]}" info >/dev/null || { warn "sudo docker também falhou."; exit 1; }
else
  warn "Sem acesso ao Docker. Entre no grupo docker (sudo usermod -aG docker \$USER e novo login) e rode de novo."
  exit 1
fi
say "$(compose version)"
if [[ -f "$ENV_FILE" ]]; then
  note "Usando o $ENV_FILE que já existe em $ROOT."
  mode=$(stat -L -c %a "$ENV_FILE")
  if [[ "$mode" != 600 && "$mode" != 400 ]]; then
    warn "$ENV_FILE está com modo $mode; outras pessoas podem ler os segredos."
    if confirm "Restringir as permissões com chmod 600?"; then
      chmod 600 "$ENV_FILE"
    else
      SKIPPED+=("chmod 600 $ENV_FILE (restringir a leitura dos segredos)")
    fi
  fi
elif confirm "Não há $ENV_FILE. Criar a partir do .env.example (só você lê)?"; then
  install -m 600 .env.example "$ENV_FILE"
  printf '  %s✓ criei%s %s\n' "$GREEN" "$RESET" "$ENV_FILE"
else
  warn "O compose precisa do $ENV_FILE."; exit 1
fi
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Senha do Decupa"
current=$(_existing DECUPA_AUTH_PASSWORD || true)
if [[ -n "$current" && "$current" != "troque-esta-senha" ]]; then
  say "DECUPA_AUTH_PASSWORD já está definida. Ela continua a mesma."
else
  say "A equipe entra no Decupa com esta senha. Use pelo menos 12 caracteres."
  while :; do
    ask_secret DECUPA_AUTH_PASSWORD "Nova senha:"
    if [[ "$DECUPA_AUTH_PASSWORD" == "troque-esta-senha" || ${#DECUPA_AUTH_PASSWORD} -lt 12 ]]; then
      warn "Senha curta demais ou ainda a do exemplo."; continue
    fi
    if [[ "$DECUPA_AUTH_PASSWORD" == *\'* || "$DECUPA_AUTH_PASSWORD" == *\\* ]]; then
      warn "A senha não pode conter apóstrofo (') nem barra invertida (\\): o compose não lê esses caracteres neste formato de .env."
      continue
    fi
    ask_secret PASSWORD_AGAIN "Repita a senha:"
    [[ "$PASSWORD_AGAIN" == "$DECUPA_AUTH_PASSWORD" ]] && break
    warn "As duas não conferem."
  done
  write_env DECUPA_AUTH_PASSWORD "$DECUPA_AUTH_PASSWORD"
  note "Guarde a senha num gerenciador de senhas: ela não aparece de novo."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Parar o que está rodando"
running=$("${DOCKER[@]}" ps --filter label=com.docker.compose.project=decupa --format '{{.Names}}  {{.Status}}' || true)
if [[ -z "$running" ]]; then
  say "Nenhum contêiner do Decupa rodando."
else
  say "Rodando agora:"
  printf '%s\n' "$running" | sed 's/^/    /'
  say "Fora do perfil, o up não remove um Caddy em execução e as portas 80/443 continuariam abertas."
  if confirm "Rodar docker compose down agora? Os volumes são preservados."; then
    compose --profile caddy down
  else
    SKIPPED+=("docker compose --profile caddy down (Caddy pode seguir com 80/443 abertas)")
    warn "Seguindo sem parar."
  fi
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Nome do Decupa na tailnet"
open_url "https://login.tailscale.com/admin/dns"
step "Confira que MagicDNS está ligado e HTTPS Certificates está habilitado."
step "Copie o Tailnet name, por exemplo tail1234.ts.net."
current_domain=$(_existing DECUPA_DOMAIN || true)
if [[ "$current_domain" == *.ts.net ]]; then
  note "O nome completo já salvo será mantido com Enter, inclusive um sufixo atribuído ao nó."
  while :; do
    ask DECUPA_DOMAIN "Nome completo do nó (.ts.net):"
    DECUPA_DOMAIN="${DECUPA_DOMAIN,,}"; DECUPA_DOMAIN="${DECUPA_DOMAIN#https://}"; DECUPA_DOMAIN="${DECUPA_DOMAIN%.}"
    [[ "$DECUPA_DOMAIN" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?\.[a-z0-9.-]+\.ts\.net$ ]] && break
    warn "Esperava o nome completo do nó, como decupa.tail1234.ts.net."
  done
  DECUPA_TAILSCALE_HOSTNAME=$(_existing DECUPA_TAILSCALE_HOSTNAME || true)
  DECUPA_TAILSCALE_HOSTNAME="${DECUPA_TAILSCALE_HOSTNAME:-${DECUPA_DOMAIN%%.*}}"
  if [[ "$DECUPA_DOMAIN" != "$current_domain" ]]; then
    DECUPA_TAILSCALE_HOSTNAME="${DECUPA_DOMAIN%%.*}"
  fi
else
  while :; do
    ask TAILNET "Tailnet name:"
    TAILNET="${TAILNET,,}"; TAILNET="${TAILNET#https://}"; TAILNET="${TAILNET#.}"; TAILNET="${TAILNET%.}"
    [[ "$TAILNET" =~ ^[a-z0-9.-]+\.ts\.net$ ]] && break
    warn "Esperava algo terminado em .ts.net."
  done
  while :; do
    ask DECUPA_TAILSCALE_HOSTNAME "Nome do nó (Enter vazio usa decupa):"
    DECUPA_TAILSCALE_HOSTNAME="${DECUPA_TAILSCALE_HOSTNAME:-decupa}"
    DECUPA_TAILSCALE_HOSTNAME="${DECUPA_TAILSCALE_HOSTNAME,,}"
    [[ "$DECUPA_TAILSCALE_HOSTNAME" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?$ ]] && break
    warn "Use só letras minúsculas, números e hífen."
  done
  DECUPA_DOMAIN="$DECUPA_TAILSCALE_HOSTNAME.$TAILNET"
fi
write_env DECUPA_TAILSCALE_HOSTNAME "$DECUPA_TAILSCALE_HOSTNAME"
write_env DECUPA_DOMAIN "$DECUPA_DOMAIN"
allowed=$(_existing DECUPA_ALLOWED_HOSTS || true)
if [[ -n "$allowed" && ",${allowed,,}," != *",$DECUPA_DOMAIN,"* ]]; then
  warn "DECUPA_ALLOWED_HOSTS=$allowed não inclui $DECUPA_DOMAIN."
  if confirm "Esvaziar DECUPA_ALLOWED_HOSTS para o compose derivar do DECUPA_DOMAIN?"; then
    write_env DECUPA_ALLOWED_HOSTS ""
  else
    SKIPPED+=("incluir $DECUPA_DOMAIN em DECUPA_ALLOWED_HOSTS")
  fi
fi
if [[ "$(_existing COMPOSE_FILE || true)" == *docker-compose.gpu.yml* ]]; then
  note "O perfil de GPU já estava ativo e continua."
  write_env COMPOSE_FILE "docker-compose.yml:docker-compose.gpu.yml:docker-compose.tailscale.yml"
else
  write_env COMPOSE_FILE "docker-compose.yml:docker-compose.tailscale.yml"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Auth key da tailnet"
if "${DOCKER[@]}" volume inspect decupa_tailscale-state >/dev/null 2>&1 \
  && confirm "O volume tailscale-state já existe, então o nó já fez login antes. Pular a auth key?"; then
  note "Sem chave: o login guardado no volume continua valendo."
else
  open_url "https://login.tailscale.com/admin/settings/keys"
  step "Clique em Generate auth key."
  step "Deixe Reusable e Ephemeral desligados. Com Ephemeral, o nó sumiria sempre que o contêiner parasse."
  step "Gere a chave e copie. Ela começa com tskey-auth-."
  while :; do
    ask_secret DECUPA_TAILSCALE_AUTHKEY "Cole a auth key:"
    [[ "$DECUPA_TAILSCALE_AUTHKEY" =~ ^tskey-[A-Za-z0-9-]+$ ]] && break
    warn "Esperava uma chave começando com tskey-, seguida só de letras, números e hífen."
  done
  write_env DECUPA_TAILSCALE_AUTHKEY "$DECUPA_TAILSCALE_AUTHKEY"
  note "Só a primeira subida usa a chave. A etapa 8 apaga ela do $ENV_FILE."
fi
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Construir e subir"
say "Vou rodar docker compose build e docker compose up -d com:"
say "  COMPOSE_FILE=$(_existing COMPOSE_FILE)"
note "O primeiro build baixa vários GB e pode demorar. O up espera o decupa ficar saudável."
confirm "Construir e subir agora?" || { warn "Parei antes do build. Rode de novo quando quiser."; exit 1; }
compose build
if ! compose up -d; then
  compose logs --tail 60
  warn "O up falhou. Os logs acima mostram o motivo."
  exit 1
fi
compose ps
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Conferir o serve"
say "Esperando o nó entrar na tailnet e aplicar o HTTPS (até 2 minutos)..."
actual=""
for _ in $(seq 1 40); do
  actual=$(serve_domain)
  [[ -n "$actual" ]] && break
  sleep 3
done
if [[ -z "$actual" ]]; then
  compose logs --tail 40 tailscale
  warn "O serve não apareceu. Nos logs acima, procure:"
  note "  ensure that HTTPS is enabled → habilite HTTPS Certificates na página DNS do painel"
  note "  invalid key / expired → gere outra auth key e rode o wizard de novo"
  exit 1
fi
compose exec -T tailscale tailscale serve status | sed 's/^/    /'
if compose exec -T tailscale tailscale serve status | grep -q "tailnet only"; then
  printf '  %s✓ serve só na tailnet%s\n' "$GREEN" "$RESET"
else
  warn "Não vi (tailnet only) acima. Confira que não diz Funnel on."
fi
if [[ "$actual" != "$DECUPA_DOMAIN" ]]; then
  warn "O nó saiu como $actual, não $DECUPA_DOMAIN (o nome já existia na tailnet?)."
  if confirm "Usar $actual como DECUPA_DOMAIN e recriar o decupa?"; then
    write_env DECUPA_DOMAIN "$actual"
    compose up -d
  else
    SKIPPED+=("DECUPA_DOMAIN=$actual (sem isso o Decupa responde 403 host não permitido)")
  fi
fi
URL="https://$DECUPA_DOMAIN"
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Guardar o login do nó"
if [[ -n "$(_existing DECUPA_TAILSCALE_AUTHKEY || true)" ]]; then
  if confirm "Apagar DECUPA_TAILSCALE_AUTHKEY do $ENV_FILE? O login já está no volume."; then
    remove_env DECUPA_TAILSCALE_AUTHKEY
  else
    SKIPPED+=("apagar DECUPA_TAILSCALE_AUTHKEY do $ENV_FILE")
  fi
fi
open_url "https://login.tailscale.com/admin/machines"
step "Ache a máquina ${DECUPA_DOMAIN%%.*}: é o próprio Decupa, não o host."
step "No menu ... da linha, escolha Disable key expiry."
note "Sem isso o nó expira em 180 dias e o acesso cai até um novo login."
pause "Feito? Enter para seguir."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "healthz pelo .ts.net"
if command -v curl >/dev/null 2>&1 && [[ "$(curl -s --max-time 8 "$URL/healthz" || true)" == *'"ok":true'* ]]; then
  HOST_IN_TAILNET=1
  PASSED+=("healthz")
  printf '  %s✓ Este host já alcança %s/healthz: {"ok":true}%s\n' "$GREEN" "$URL" "$RESET"
  pause
else
  say "Este host não alcança $URL. É o esperado: quem entra na tailnet é o contêiner."
  say "Num aparelho da equipe com o Tailscale ligado, rode:"
  printf '\n    %scurl %s/healthz%s\n\n' "$BOLD" "$URL" "$RESET"
  say 'Esperado: {"ok":true}'
  note "403 host não permitido → DECUPA_DOMAIN diferente do nome do nó (etapa 7)."
  note "Nome não resolve → aparelho fora da tailnet ou MagicDNS desligado nele."
  check 'Saiu {"ok":true}?' "healthz"
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Login no navegador"
if (( HOST_IN_TAILNET )); then open_url "$URL"; else say "No navegador de um aparelho da tailnet, abra:"; fi
printf '\n    %s%s%s\n\n' "$BOLD" "$URL" "$RESET"
step "Entre com a senha do Decupa e seu nome. Você chega à tela Projetos."
note "Opcional: DevTools → Application → Cookies → decupa_session aparece com Secure."
check "Entrou e viu a tela Projetos?" "login"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Upload de uma Mídia"
step "Clique em Novo Projeto."
step "Nome do Projeto: Teste Tailscale. Fluxo: Montagem."
step "Em Enviar do computador, escolha um vídeo curto (1 a 2 minutos basta)."
step "Espere o envio terminar e clique em Criar Projeto. O Projeto abre sozinho."
note "O Projeto de teste fica na lista: a interface não tem exclusão de Projeto."
check "O envio terminou e o Projeto abriu?" "upload"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Playback"
step "No Projeto, dê play no vídeo enviado."
step "Pule para o meio e para perto do fim. Ele deve tocar sem baixar o arquivo inteiro antes."
note "Opcional: DevTools → Network, filtro Media → a requisição do vídeo responde 206."
check "O vídeo tocou e os pulos funcionaram?" "playback"

finish
if (( ${#FAILED[@]} )); then
  warn "Conferências que não passaram: ${FAILED[*]}"
  note "Diagnóstico: docker compose logs decupa tailscale e a seção Tailscale de docs/implantacao-docker.md."
else
  printf '  %s✓ Conferências que passaram: %s%s\n' "$GREEN" "${PASSED[*]}" "$RESET"
  note "A equipe acessa em $URL."
fi
note "Antes do uso real: docker compose run --rm decupa models fetch (baixa os modelos de fala)."
note "Inclua tailscale-state no backup, junto de decupa-config, decupa-projects e decupa-media."
printf '\n'
}

run_wizard "$@"; exit
